// ❌ Impure — depends on external state
let tax = 0.1;
function calculateTotal(price) {
  return price + price * tax;  // 'tax' can change!
}

// ✅ Pure — all inputs are explicit
function calculateTotalPure(price, taxRate) {
  return price + price * taxRate;
}

// ❌ Impure — modifies external state
let count = 0;
function increment() {
  count++;  // side effect!
}

// ✅ Pure — returns new value
function incrementPure(n) {
  return n + 1;
}
console.log(incrementPure(5));  // 6

// ❌ Mutable — modifies original
let user = { name: "Alex", age: 25 };
user.age = 26;  // original changed!

// ✅ Immutable — creates new object
let user2 = { ...user, age: 26 };
console.log(user);    // { name: "Alex", age: 25 }
console.log(user2);   // { name: "Alex", age: 26 }

// Arrays
let items = [1, 2, 3];
let updated = [...items, 4];        // add
let removed = items.filter(x => x !== 2);  // remove
let replaced = items.map(x => x === 2 ? 20 : x);  // update

// Higher-order function
function repeat(times, fn) {
  for (let i = 0; i < times; i++) fn(i);
}

repeat(3, (i) => console.log("Iteration " + i));

// Currying
function multiply(a) {
  return function(b) {
    return a * b;
  };
}

let double = multiply(2);
let triple = multiply(3);

console.log(double(5));   // 10
console.log(triple(5));   // 15

// Practical: create specialized functions
let add10 = (x) => x + 10;
let numbers = [1, 2, 3];
console.log(numbers.map(add10));  // [11, 12, 13]

// Compose: right to left
const compose = (...fns) => (x) => fns.reduceRight((acc, fn) => fn(acc), x);

// Pipe: left to right
const pipe = (...fns) => (x) => fns.reduce((acc, fn) => fn(acc), x);

// Simple functions
const addTax = (price) => price * 1.1;
const applyDiscount = (price) => price * 0.9;
const round = (price) => Math.round(price * 100) / 100;

// Compose (right to left)
const processPrice = compose(round, applyDiscount, addTax);
console.log(processPrice(100));  // 99

// Pipe (left to right)
const processPricePipe = pipe(addTax, applyDiscount, round);
console.log(processPricePipe(100));  // 99
